package cl.bolsillo.app;
import android.app.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.view.*;import android.widget.*;

final class Modern {
 static void fitAmount(TextView view,int min,int max){view.setMaxLines(1);view.setEllipsize(android.text.TextUtils.TruncateAt.END);view.setAutoSizeTextTypeUniformWithConfiguration(min,max,1,android.util.TypedValue.COMPLEX_UNIT_SP);}
 static LinearLayout column(Context c){LinearLayout l=new LinearLayout(c);l.setOrientation(1);l.setClipChildren(false);l.setClipToPadding(false);return l;}
 static LinearLayout row(Context c){LinearLayout l=new LinearLayout(c);l.setGravity(Gravity.CENTER_VERTICAL);l.setClipChildren(false);l.setClipToPadding(false);return l;}
 static View quickAction(MainActivity a,String icon,String label,Runnable action){LinearLayout tile=surface(a);tile.setGravity(Gravity.CENTER);tile.addView(Icons.badge(a,icon,40),new LinearLayout.LayoutParams(a.dp(40),a.dp(40)));TextView name=text(a,label,14,Glass.ink(a),true);name.setSingleLine(true);name.setPadding(0,a.dp(10),0,0);tile.addView(name);tile.setContentDescription(label);press(tile,action);return tile;}
 static TextView text(Context c,String s,int size,int color,boolean bold){TextView t=Glass.text(c,s,size,bold);t.setTextColor(Glass.semantic(c,color));return t;}
 static LinearLayout surface(Context c){LinearLayout l=Glass.column(c);l.setPadding(Glass.dp(c,17),Glass.dp(c,16),Glass.dp(c,17),Glass.dp(c,16));l.setBackground(Glass.surface(c,224));l.setClipToOutline(true);l.setElevation(0);return l;}
 static void add(LinearLayout parent,View child,int top){LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.topMargin=Glass.dp(parent.getContext(),top);parent.addView(child,lp);}
 static TextView chip(Context c,String label,int color){TextView t=text(c,label,11,color,true);t.setGravity(Gravity.CENTER);t.setPadding(Glass.dp(c,9),Glass.dp(c,6),Glass.dp(c,9),Glass.dp(c,6));t.setBackground(Glass.round(c,(color&0xffffff)|(Glass.dark(c)?0x23000000:0x18000000),10));return t;}
 static View iconButton(Context c,String icon,String description,Runnable action){android.widget.FrameLayout frame=new android.widget.FrameLayout(c);frame.setBackground(Glass.surface(c,180));ImageView image=Icons.view(c,icon,Glass.ink(c),22);android.widget.FrameLayout.LayoutParams p=new android.widget.FrameLayout.LayoutParams(Glass.dp(c,22),Glass.dp(c,22),Gravity.CENTER);frame.addView(image,p);frame.setContentDescription(description);frame.setMinimumWidth(Glass.dp(c,44));frame.setMinimumHeight(Glass.dp(c,44));press(frame,action);return frame;}
 static void press(View v,Runnable action){Drawable background=v.getBackground();if(!(background instanceof RippleDrawable))v.setBackground(new RippleDrawable(android.content.res.ColorStateList.valueOf(Glass.alpha(Glass.accent(v.getContext()),45)),background,background==null?Glass.round(v.getContext(),Color.WHITE,20):null));v.setClickable(true);v.setFocusable(true);v.setOnClickListener(w->{w.performHapticFeedback(HapticFeedbackConstants.CLOCK_TICK);action.run();});}
 static LinearLayout item(Context c,String icon,String title,String subtitle,String trailing,int tint,Runnable action){LinearLayout row=row(c);row.setPadding(Glass.dp(c,14),Glass.dp(c,13),Glass.dp(c,14),Glass.dp(c,13));row.setBackground(Glass.surface(c,222));row.setMinimumHeight(Glass.dp(c,76));ImageView badge=Icons.badge(c,icon,44);row.addView(badge,new LinearLayout.LayoutParams(Glass.dp(c,44),Glass.dp(c,44)));LinearLayout texts=column(c);texts.setPadding(Glass.dp(c,12),0,Glass.dp(c,8),0);TextView name=text(c,title,15,Glass.ink(c),true);name.setSingleLine(true);name.setEllipsize(android.text.TextUtils.TruncateAt.END);texts.addView(name);if(!subtitle.isEmpty()){TextView detail=text(c,subtitle,11,Glass.subtle(c),false);detail.setMaxLines(2);detail.setEllipsize(android.text.TextUtils.TruncateAt.END);texts.addView(detail);}row.addView(texts,new LinearLayout.LayoutParams(0,-2,1));if(!trailing.isEmpty()){TextView amount=text(c,trailing,14,tint,true);amount.setGravity(Gravity.END);if(trailing.length()>13||c.getResources().getConfiguration().fontScale>1.2f){amount.setTextSize(18);amount.setPadding(0,Glass.dp(c,6),0,0);fitAmount(amount,12,18);texts.addView(amount,new LinearLayout.LayoutParams(-1,-2));}else{amount.setMaxWidth(Glass.dp(c,135));fitAmount(amount,10,14);row.addView(amount);}}else if(action!=null)row.addView(Icons.view(c,"chevron",Glass.subtle(c),17),new LinearLayout.LayoutParams(Glass.dp(c,17),Glass.dp(c,17)));row.setContentDescription(title+(subtitle.isEmpty()?"":". "+subtitle)+(trailing.isEmpty()?"":". "+trailing));if(action!=null)press(row,action);return row;}
 static void section(MainActivity a,String title,String link,MainActivity.Work action){LinearLayout r=row(a);r.setPadding(0,a.dp(22),0,a.dp(9));TextView heading=text(a,title,19,Glass.ink(a),true);heading.setPadding(0,0,a.dp(12),0);r.addView(heading,new LinearLayout.LayoutParams(0,-2,1));if(!link.isEmpty()){TextView b=text(a,link,12,Glass.accent(a),true);b.setMinHeight(a.dp(44));b.setGravity(Gravity.CENTER_VERTICAL);b.setPadding(a.dp(8),0,0,0);press(b,()->a.attempt(action));r.addView(b);}a.body.addView(r);}
 static LinearLayout stat(MainActivity a,String icon,String label,String value,int color){LinearLayout l=surface(a);LinearLayout top=row(a);top.addView(Icons.view(a,icon,color,18),new LinearLayout.LayoutParams(a.dp(18),a.dp(18)));TextView name=text(a,label,12,Glass.subtle(a),false);name.setPadding(a.dp(7),0,0,0);name.setSingleLine(true);name.setEllipsize(android.text.TextUtils.TruncateAt.END);name.setAutoSizeTextTypeUniformWithConfiguration(10,12,1,android.util.TypedValue.COMPLEX_UNIT_SP);top.addView(name,new LinearLayout.LayoutParams(0,-2,1));l.addView(top);TextView n=text(a,value,23,Glass.ink(a),true);n.setPadding(0,a.dp(12),0,0);fitAmount(n,11,23);l.addView(n);return l;}
 static void pair(MainActivity a,View first,View second){LinearLayout row=row(a);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);p.rightMargin=a.dp(6);row.addView(first,p);LinearLayout.LayoutParams q=new LinearLayout.LayoutParams(0,-2,1);q.leftMargin=a.dp(6);row.addView(second,q);add(a.body,row,12);}
 static void empty(MainActivity a,String icon,String title,String detail,String button,MainActivity.Work action){LinearLayout l=surface(a);l.addView(Icons.badge(a,icon,44),new LinearLayout.LayoutParams(a.dp(44),a.dp(44)));TextView t=text(a,title,18,Glass.ink(a),true);t.setPadding(0,a.dp(12),0,a.dp(6));l.addView(t);l.addView(text(a,detail,13,Glass.subtle(a),false));if(!button.isEmpty()){Button b=Glass.button(a,button);l.addView(b);b.setOnClickListener(v->a.attempt(action));}add(a.body,l,8);}
 static void help(MainActivity a,String title,String detail){a.confirm(title,detail,()->{});}
 static String iconFor(String value){String brand=Icons.brand(value);if(!brand.isEmpty())return brand;String n=BankNotificationParser.normalize(value);if(n.contains("regalo")||n.contains("obsequio"))return "gift";if(n.contains("mascota"))return "pets";if(n.contains("viaje")||n.contains("vacacion"))return "travel";if(n.contains("deporte")||n.contains("gimnasio"))return "sport";if(n.contains("donacion"))return "donation";if(n.contains("tecnologia"))return "technology";if(n.contains("cuidado personal")||n.contains("belleza"))return "care";if(n.contains("impuesto"))return "tax";if(n.contains("reembolso"))return "income";if(n.contains("eliminar")||n.contains("borrar"))return "delete";if(n.startsWith("editar"))return "edit";if(n.contains("historial"))return "history";if(n.contains("duplicar")||n.startsWith("crear")||n.startsWith("anadir"))return "plus";if(n.contains("salario")||n.contains("sueldo")||n.contains("remunera"))return "salary";if(n.contains("trabaj")||n.contains("jornada")||n.contains("cliente"))return "work";if(n.contains("persona")||n.contains("prestam")||n.contains("compart")||n.contains("deuda"))return "people";if(n.contains("automat")||n.contains("aprendiz")||n.contains("deteccion"))return "auto";if(n.contains("previsto")||n.contains("programar")||n.contains("fecha"))return "calendar";if(n.contains("aviso")||n.contains("notificacion"))return "bell";if(n.contains("respaldo")||n.contains("exportar"))return "download";if(n.contains("importar"))return "upload";if(n.contains("apariencia")||n.contains("ajustes"))return "settings";if(n.contains("movimiento")||n.contains("detalle"))return "activity";if(n.contains("ingreso")||n.contains("cobro"))return "income";if(n.contains("aliment")||n.contains("cafe")||n.contains("supermerc"))return "food";if(n.contains("transporte")||n.contains("uber"))return "transport";if(n.contains("educa")||n.contains("colegi")||n.contains("univers")||n.contains("escuela")||n.contains("curso"))return "education";if(n.contains("salud")||n.contains("medic")||n.contains("farmac")||n.contains("clinica")||n.contains("dental")||n.contains("hospital"))return "health";if(n.contains("ocio")||n.contains("entreten")||n.contains("cine")||n.contains("teatro"))return "leisure";if(n.contains("hogar")||n.contains("vivienda")||n.contains("arriendo")||n.contains("alquiler"))return "home";if(n.contains("servicio")||n.contains("electric")||n.contains("internet")||n.contains("telefon")||n.matches(".*\\b(agua|gas|luz)\\b.*"))return "utilities";if(n.contains("compra")||n.contains("shopping")||n.contains("vestuario")||n.contains("ropa")||n.contains("tienda"))return "shopping";if(n.contains("cuenta")||n.contains("tarjeta"))return "card";if(n.contains("suscrip")||n.contains("recurrent"))return "subscription";if(n.contains("meta")||n.contains("ahorro"))return "target";if(n.contains("presup")||n.contains("informe"))return "chart";if(n.contains("categor"))return "tag";return "wallet";}
}

